"""User-facing replies, built from the shared i18n catalogs (never generated by the LLM)."""

from __future__ import annotations

from typing import Literal

from shared.domain.energy import BodyProfile
from shared.ports.translator import Translator

from nutrition.domain.meal import Meal

Confidence = Literal["high", "medium", "low"]


def meal_confirmation(meal: Meal, *, confidence: Confidence, locale: str, tr: Translator) -> str:
    names = [
        tr.t(
            "nutrition.log_meal.item_with_amount",
            locale,
            name=item.name,
            amount=tr.number(item.amount_g, locale),
        )
        if item.amount_g is not None
        else item.name
        for item in meal.items
    ]
    totals = meal.totals
    text = tr.t(
        "nutrition.log_meal.confirmed",
        locale,
        items=", ".join(names),
        kcal=tr.number(totals.kcal, locale),
        protein=tr.number(totals.protein_g, locale),
        fat=tr.number(totals.fat_g, locale),
        carbs=tr.number(totals.carbs_g, locale),
    )
    if confidence == "low":
        text = f"{text} {tr.t('nutrition.log_meal.low_confidence', locale)}"
    return text


def body_profile_saved(
    changes: BodyProfile, *, locale: str, tr: Translator, cleared_fields: tuple[str, ...] = ()
) -> str:
    parts: list[str] = []
    if changes.height_cm is not None:
        parts.append(
            tr.t(
                "nutrition.body_profile.fields.height_cm",
                locale,
                value=tr.number(changes.height_cm, locale),
            )
        )
    if changes.age is not None:
        parts.append(tr.t("nutrition.body_profile.fields.age", locale, value=changes.age))
    if changes.sex is not None:
        sex = tr.t(f"nutrition.body_profile.sex.{changes.sex.value}", locale)
        parts.append(tr.t("nutrition.body_profile.fields.sex", locale, value=sex))
    if changes.activity_level is not None:
        level = tr.t(f"nutrition.body_profile.activity.{changes.activity_level.value}", locale)
        parts.append(tr.t("nutrition.body_profile.fields.activity_level", locale, value=level))
    if changes.calorie_goal_override is not None:
        parts.append(
            tr.t(
                "nutrition.body_profile.fields.calorie_goal_override",
                locale,
                value=tr.number(changes.calorie_goal_override, locale),
            )
        )
    parts.extend(
        tr.t(
            "nutrition.body_profile.cleared",
            locale,
            field=tr.t(f"nutrition.body_profile.names.{key}", locale),
        )
        for key in cleared_fields
    )
    return tr.t("nutrition.body_profile.saved", locale, fields=", ".join(parts))
